import React from 'react';
import { Search, Bell, Calendar, Menu, X } from 'lucide-react';

const TopBar = ({ mobileMenuOpen, setMobileMenuOpen, location, notifications }) => {
  const getPageTitle = () => {
    const path = location.pathname;
    const titles = {
      '/dashboard': 'Tableau de bord',
      '/dashboard/users': 'Gestion des utilisateurs',
      '/dashboard/products': 'Gestion des produits',
      '/dashboard/orders': 'Commandes',
      '/dashboard/analytics': 'Analytique',
      '/dashboard/messages': 'Messages',
      '/dashboard/settings': 'Paramètres',
    };
    return titles[path] || 'Tableau de bord';
  };

  return (
    <header className="sticky top-0 z-40 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl border-b border-neutral-200/50 dark:border-neutral-800/50">
      <div className="flex items-center justify-between px-6 py-4">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="lg:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800"
          >
            {mobileMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
          </button>
          <h2 className="text-xl font-bold text-neutral-900 dark:text-white">{getPageTitle()}</h2>
        </div>

        <div className="flex items-center space-x-4">
          {/* Search */}
          <div className="relative hidden md:block">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="h-5 w-5 text-neutral-400" />
            </div>
            <input
              type="search"
              placeholder="Rechercher..."
              className="pl-10 pr-4 py-2 w-64 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 transition-all"
            />
          </div>

          {/* Notifications */}
          <div className="relative">
            <button className="relative p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800">
              <Bell className="h-5 w-5" />
              {notifications.filter(n => n.unread).length > 0 && (
                <span className="absolute -top-1 -right-1 h-3 w-3 bg-red-500 rounded-full border-2 border-white dark:border-neutral-900"></span>
              )}
            </button>
          </div>

          {/* Calendar */}
          <button className="hidden md:flex items-center space-x-2 px-4 py-2 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 transition-colors">
            <Calendar className="h-5 w-5" />
            <span>Jan 15, 2024</span>
          </button>
        </div>
      </div>
    </header>
  );
};

export default TopBar;
